<template><div><div class="page-head"><div><span>PHM INTEGRATION / KNOWLEDGE</span><h2>FMECA 鏁呴殰鐭ヨ瘑搴?/h2><p>缁熶竴绠＄悊鏁呴殰妯″紡銆佸師鍥犱笌鍗卞绛夌骇锛屾敮鎸佺瓫閫夊拰璇︽儏鏌ョ湅銆?/p></div><el-button :loading="loading" @click="load">鍒锋柊鏁版嵁</el-button></div><div class="stats"><el-card><small>璁板綍鎬绘暟</small><strong>{{rows.length}}</strong></el-card><el-card><small>楂樺嵄璁板綍</small><strong class="danger">{{highRisk}}</strong></el-card><el-card><small>娑夊強閮ㄤ欢</small><strong>{{components}}</strong></el-card></div><el-card shadow="never"><div class="filters"><el-input v-model="keyword" clearable placeholder="鎼滅储閮ㄤ欢銆佹晠闅滄ā寮忔垨鍘熷洜" style="width:280px"/><el-select v-model="severity" clearable placeholder="鍗卞绛夌骇" style="width:150px"><el-option v-for="x in severities" :key="x" :label="x" :value="x"/></el-select><el-select v-model="component" clearable placeholder="閮ㄤ欢" style="width:180px"><el-option v-for="x in componentOptions" :key="x" :label="x" :value="x"/></el-select><el-button @click="reset">娓呯┖绛涢€?/el-button></div><el-table :data="filtered" stripe v-loading="loading" @row-click="show"><el-table-column prop="id" label="搴忓彿" width="70"/><el-table-column prop="component" label="閮ㄤ欢" width="150"/><el-table-column prop="fault_name" label="鏁呴殰妯″紡" width="180"/><el-table-column prop="fault_prob" label="鏁呴殰姒傜巼" width="110"/><el-table-column prop="fault_reason" label="鍙兘鍘熷洜" min-width="240"/><el-table-column label="鍗卞绛夌骇" width="120"><template #default="s"><el-tag :type="isHigh(s.row.degree_harm)?'danger':'warning'">{{s.row.degree_harm||'鏈垎绾?}}</el-tag></template></el-table-column><el-table-column label="鎿嶄綔" width="90"><template #default="s"><el-button link type="primary" @click.stop="show(s.row)">璇︽儏</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!filtered.length" description="娌℃湁鍖归厤鐨勬晠闅滆褰?/></el-card><el-drawer v-model="drawer" title="鏁呴殰妯″紡璇︽儏" size="500px"><el-descriptions v-if="current" :column="1" border><el-descriptions-item v-for="(v,k) in detailItems" :key="k" :label="k">{{v||'鈥?}}</el-descriptions-item></el-descriptions></el-drawer></div></template>
<script setup>import{ref,computed,onMounted}from'vue';import{ElMessage}from'element-plus';const rows=ref([]),loading=ref(false),keyword=ref(''),severity=ref(''),component=ref(''),drawer=ref(false),current=ref(null),severities=['鈪?,'鈪?,'鈪?,'鈪?];const load=async()=>{loading.value=true;try{const r=await fetch('/api/v1/integrations/algorithm-assets/fmeca/');if(!r.ok)throw Error();rows.value=(await r.json()).results||[]}catch{ElMessage.error('FMECA 鏁版嵁鍔犺浇澶辫触')}finally{loading.value=false}};onMounted(load);const componentOptions=computed(()=>[...new Set(rows.value.map(x=>x.component).filter(Boolean))]);const filtered=computed(()=>{const k=keyword.value.trim().toLowerCase();return rows.value.filter(x=>(!k||Object.values(x).join(' ').toLowerCase().includes(k))&&(!severity.value||x.degree_harm===severity.value)&&(!component.value||x.component===component.value))});const highRisk=computed(()=>rows.value.filter(x=>String(x.degree_harm||'').includes('鈪?)).length),components=computed(()=>componentOptions.value.length);const isHigh=v=>String(v||'').includes('鈪?);const reset=()=>{keyword.value='';severity.value='';component.value=''};const show=row=>{current.value=row;drawer.value=true};const detailItems=computed(()=>current.value?{'閮ㄤ欢':current.value.component,'鏁呴殰妯″紡':current.value.fault_name,'鏁呴殰姒傜巼':current.value.fault_prob,'鍙兘鍘熷洜':current.value.fault_reason,'褰卞搷':current.value.fault_effect,'鍗卞绛夌骇':current.value.degree_harm,'妫€娴嬫柟娉?:current.value.detection_method}:{});</script>
<style scoped>.page-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.page-head span{font-size:11px;color:#2c82e7;font-weight:700;letter-spacing:1px}.page-head h2{margin:7px 0}.page-head p{margin:0;color:#8391a5}.stats{display:flex;gap:14px;margin-bottom:16px}.stats .el-card{flex:1}.stats small{color:#8997a9}.stats strong{display:block;font-size:25px;margin-top:6px}.danger{color:#e45656}.filters{display:flex;gap:10px;margin-bottom:15px;flex-wrap:wrap}.el-card{border-radius:11px}</style>

